from datetime import datetime, timezone

def main(input):
    config = input["config"]
    logins = input["logins"]
    max_hours = int(input["max_hours"])
    fallback_channel = input["fullback_slack_chnnel"]  # match your exact field name

    now = datetime.now(timezone.utc)

    def parse(ts):
        return datetime.fromisoformat(ts.replace('Z', '+00:00'))

    # squash → latest login per (user_id, application)
    latest = {}
    for r in logins:
        key = (r['UserId'], r['Application'])
        t = parse(r['LoginTime'])
        if key not in latest or t > latest[key]:
            latest[key] = t

    # coverage guard
    times = [parse(r['LoginTime']) for r in logins]
    coverage_hours = round((now - min(times)).total_seconds() / 3600, 1) if times else 0

    # compare
    failing = []
    for c in config:
        key = (c['user_id'], c['app_name'])
        last = latest.get(key)
        if last is None:
            hours = None
            stale = True
        else:
            hours = round((now - last).total_seconds() / 3600, 1)
            stale = hours > max_hours
        if stale:
            failing.append({'name': c['name'], 'hours': hours})

    lines = []
    for f in failing:
        ago = "no login in window" if f['hours'] is None else "{}h ago".format(f['hours'])
        lines.append("- {}: last login {}".format(f['name'], ago))

    if failing:
        subject = "⚠️ {} SF integration(s) stale".format(len(failing))
        body = "Not logged in within {}h:\n\n".format(max_hours) + "\n".join(lines)
    else:
        subject = "✅ SF integrations healthy ({}/{})".format(len(config), len(config))
        body = "All monitored integrations logged in within {}h.".format(max_hours)

    return {
        'alert_count': len(failing),
        'coverage_hours': coverage_hours,
        'subject': subject,
        'body': body,
        'channel': fallback_channel
    }
